"""Reproducible authoring checkpoint for records 131--140.

All mathematical reconstructions are explicitly labelled in the JSON fields.
This script writes only this fragment's directory.
"""
import csv, json, pathlib, re
ROOT = pathlib.Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]

def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(record,pages,kind,title,notes,statement,fate,refs=(),cls='E',literal='correct with missing hypotheses',match='exact',verification='read the result',reconstruction='',status='',problem='',worth='',confidence='high',speaker=None):
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1967-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or r'As of November 2026, the qualified statement above is established; the distinctions from the notebook wording remain essential.',literal_correctness=literal,publication_match=match,verification=verification,development='annotated' if reconstruction or literal=='false as written' else 'none',problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker: d['speaker']=speaker
    items.append(d)
    return d['id']
def correction(page,place,old,new,evidence,applies='both',kind='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=old,should_read=new,evidence=evidence,applies_to=applies,type=kind))
def save():
    talks.sort(key=lambda x:x['record'])
    items.sort(key=lambda x:(x['record'],int(x['id'].split('.')[-1])))
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        clean=json.loads(json.dumps(data).replace("\\\\'", "'"))
        (ROOT/(name+'.json')).write_text(json.dumps(clean,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(131,'1967-09-18','A. A. Kirillov','P000208-P000210','Local orbit character formula and the rotation group',r'The actual Kirillov heading occupies P000208 and the beginning of P000209. It announces an orbit formula for irreducible characters, explicitly without proof, and tests it on \(SO(3)\). The notebook also lists future talks on logic, the continuum hypothesis, Lidskii on eigenvalue asymptotics, and work of Kirillov, Kazhdan, and Graev. The mathematical continuation is Kirillov\'s 1968 character paper, received on 18 October 1967; its proved cases must be distinguished from the unrestricted announcement.')
item(131,'P000208','method','Local orbit formula for characters',r'The heading says \ru{без доказательства или противоречащих примеров}. Near the identity it proposes \(\chi(x)=p(x)^{-1/2}\int_\Omega e^{i\langle F,x\rangle}\beta(F)\) for irreducible representations of Lie groups.',r'For a connected simply connected nilpotent Lie group, the irreducible unitary representation associated with a coadjoint orbit has distribution character equal, in exponential coordinates and with compatible Fourier conventions, to the Fourier transform of the canonical orbital measure. For compact connected groups the corresponding local formula uses the orbit through the highest weight plus \(\rho\), and the square root of the exponential Jacobian. Neither statement is an unrestricted formula for every irreducible representation of every Lie group.',r'\citet[Introduction and the nilpotent and compact cases]{kirillov1968characters} develops the announced formula; the manuscript was received 18 October 1967 and published in 1968. The nilpotent orbit correspondence was already available in \citet{kirillov1962unitary}. The publication match is partial because the notebook suppresses the admissibility, normalization, and representation-class restrictions.',('kirillov1968characters','kirillov1962unitary'),cls='A',match='partial',reconstruction=r'The two precise proved settings replace the notebook\'s unrestricted scope. No general orbit-method conjecture is silently converted into a theorem.',status=r'As of November 2026, these nilpotent and compact character formulas are established. The universal formulation in the notes is too broad to have a single affirmative status.')
item(131,'P000208','definition','Distribution character and the missing trace',r'For a finite-dimensional representation the notes give \(\chi(g)=\operatorname{tr}T(g)\). In the general case they write \(\langle\chi,\varphi\rangle=\int_G\varphi(g)T(g)\,dg\), adding that the latter already has a trace.',r'For a representation for which \(T(\varphi)=\int_G\varphi(g)T(g)\,dg\) is trace class for every \(\varphi\in C_c^\infty(G)\), its distribution character is \(\Theta_T(\varphi)=\operatorname{tr}T(\varphi)\). The integral itself is an operator, not a scalar distribution value; trace-class admissibility is an additional hypothesis.',r'This is the character convention used in \citet[Introduction]{kirillov1968characters}. The notebook has omitted the outer trace while preserving an explanatory phrase that makes the intended correction clear.',('kirillov1968characters',),literal='false as written',match='partial',reconstruction=r'The trace-class condition and the outer trace are explicit editorial repairs.')
item(131,'P000208-P000209','construction','Canonical form and measure on a coadjoint orbit',r'The form \(\beta\) is said to be constructed from the structure constants; the final line mentions integrals of integral forms over cycles of the orbit.',r'At \(F\in\mathfrak g^*\), the Kirillov form on the coadjoint orbit is \(\omega_F(\operatorname{ad}_X^*F,\operatorname{ad}_Y^*F)=\langle F,[X,Y]\rangle\), up to the sign convention for the coadjoint action. It is closed and nondegenerate. On an orbit of dimension \(2d\), the corresponding Liouville measure is a fixed Fourier-normalized multiple of \(\omega^d/d!\).',r'The canonical orbital measure is part of the framework in \citet[Introduction]{kirillov1968characters}, extending the earlier nilpotent setting of \citet{kirillov1962unitary}. The notebook\'s cycle phrase does not give a separate computable formula for \(\beta\).',('kirillov1968characters','kirillov1962unitary'),reconstruction=r'The symplectic formula makes precise the otherwise unspecified construction from structure constants; the sign and Fourier normalization are deliberately not inferred from the notebook.')
item(131,'P000208-P000209','remark','Integrality and the shifted compact orbit',r'Only certain orbits satisfying integrality conditions are to occur. The rotation example selects \(\lambda=2n+1\).',r'Prequantization of a symplectic orbit requires \([\omega/(2\pi)]\) to be integral. Equivariance under a specified group can impose a stronger lattice condition. In the compact character formula the orbit is shifted by \(\rho\); therefore an unshifted assertion that every integral orbit directly labels a character is insufficient. For \(SO(3)\), the representations have integral spin \(n\geq0\), while the character formula below contains \(2n+1\).',r'\citet[compact-group discussion]{kirillov1968characters} supplies the compact character setting. The notes announce an integrality requirement but do not state which lattice or shift is intended.',('kirillov1968characters',),match='partial',reconstruction=r'Prequantization, group equivariance, and the \(\rho\)-shift are separated here rather than merged into the ambiguous word integrality.')
item(131,'P000208','claim','Exponential Haar density for the rotation example',r'The notebook visibly writes \(p(x)=\sin\tau/\tau\), without a square, and then applies \(p^{-1/2}\).',r'If \(\tau\) denotes half the rotation angle, the exponential-coordinate Haar Jacobian, normalized at zero, is \(j(x)=(\sin\tau/\tau)^2\). If \(\theta\) is the full angle, it is \((\sin(\theta/2)/(\theta/2))^2\). Its square root, rather than the density itself, is \(\sin\tau/\tau\) near zero.',r'The determinant factor in the compact case of \citet{kirillov1968characters} and the elementary eigenvalues \(0,\pm 2i\tau\) of \(\operatorname{ad}_x\) identify the missing square. The displayed formula is faithfully transcribed, not an OCR mistake.',('kirillov1968characters',),literal='false as written',match='partial',reconstruction=r'The half-angle convention is chosen to make the subsequent character formula consistent; the notebook does not explicitly specify this normalization.')
item(131,'P000208-P000209','claim','Fourier transform of the spherical orbital measure',r'The notes give \((\delta_{S_\lambda})^\vee=\sin(\lambda\tau)/\tau\), then call \(\beta\) ordinary surface area.',r'With Fourier kernel \(e^{i\langle F,x\rangle}\) and Euclidean area \(dS\) on the sphere of radius \(\lambda>0\), \(\int_{S_\lambda}e^{i\langle F,x\rangle}dS=4\pi\lambda\sin(\lambda|x|)/|x|\). The measure \(dS/(4\pi\lambda)\) gives the notebook\'s transform and has mass \(\lambda\).',r'This direct spherical-coordinate calculation fixes the normalization required by the compact orbit formula of \citet{kirillov1968characters}. The words ordinary surface cannot be read literally together with the displayed equality under this Fourier convention.',('kirillov1968characters',),literal='false as written',match='partial',reconstruction=r'The calculation is an editorial normalization check, not a new character theorem.')
item(131,'P000209','theorem','The irreducible characters of SO(3)',r'The answer is \(\chi(x)=\sin(\lambda\tau)/\sin\tau\), for \(\lambda=2n+1\).',r'For the irreducible \((2n+1)\)-dimensional representation of \(SO(3)\), a rotation through angle \(\theta\) has character \(\chi_n(\theta)=\sin((n+\tfrac12)\theta)/\sin(\theta/2)\), interpreted continuously at multiples of \(2\pi\). Setting \(\tau=\theta/2\) gives exactly the recorded expression and \(\chi_n(e)=2n+1\).',r'This is the rank-one compact character formula, used as the test case for \citet[compact case]{kirillov1968characters}. It was known before the lecture, although its orbit interpretation is the point of the new presentation.',('kirillov1968characters',),reconstruction=r'The parameter is explicitly the half-angle, and the removable singularities are filled in.')
correction('P000208','Distribution-character definition',r'\langle\chi,\varphi\rangle=\int\varphi(g)T(g)dg',r'\langle\chi,\varphi\rangle=\operatorname{tr}\int\varphi(g)T(g)dg','The scan omits the outer trace; its next phrase says the operator has a trace. Trace-class hypotheses must also be stated.')
correction('P000208','SO(3) Haar density',r'p=\sin\tau/\tau',r'p=(\sin\tau/\tau)^2','The scan has no square. The exponential Jacobian and the following p^{-1/2} character formula require the square under the half-angle convention.')
correction('P000208-P000209','Spherical Fourier transform and beta',r'ordinary surface area; transform \sin(\lambda\tau)/\tau',r'dS/(4\pi\lambda) for the written transform','Direct integration with Fourier kernel exp(i<F,x>) gives 4 pi lambda sin(lambda tau)/tau for ordinary area.')

talk(132,'1967-09-18','D. B. Fuchs','P000208-P000213','Classifying noncompact groups over Hausdorff bases',r'The Fuchs heading begins midway through P000209 and ends on P000212 before the date 25 September. The discussion changes the category of bases and bundle charts so that noncompact groups retain characteristic information invisible to ordinary homotopy classification. The nonregular ray quotient and the failure of a cone-based definition are central. The exact research continuation is \citet{gelfandfuchs1967topology}, received 15 July 1967; parts of the programme were therefore already circulating before this lecture.')
item(132,'P000209','definition','Ordinary universal principal bundles and characteristic classes',r'\(E_G\to B_G\) is called universal; \(\pi_k(E_G)=0\) for \(k>0\). Characteristic classes are \(H^q(B_G;A)\), and more generally \(h(B_G)\) for a contravariant homotopy functor.',r'For numerable principal bundles over paracompact Hausdorff bases, a contractible free universal \(G\)-space classifies bundles by homotopy classes \([X,BG]\). A class \(a\in H^q(BG;A)\) gives \(c_a(P)=f_P^*a\). The analogous statement for a contravariant homotopy functor uses the universal pullback class and its naturality. Vanishing higher homotopy groups alone must be supplemented by connectedness and suitable CW-type hypotheses to infer contractibility.',r'This is the conventional background contrasted with the new category in \citet[Introduction]{gelfandfuchs1967topology}. The notebook uses aspherical for weak contractibility, rather than the modern condition of vanishing \(\pi_k\) only for \(k>1\).',('gelfandfuchs1967topology',),match='partial',reconstruction=r'Numerability, paracompactness, and the distinction between weak and actual contractibility are supplied.')
item(132,'P000209','theorem','Loss of noncompact information under homotopy equivalence',r'A maximal compact subgroup is said to be homotopy equivalent to the group, and their classifying spaces homotopy equivalent.',r'If \(G\) is a Lie group with finitely many connected components and \(K\) a maximal compact subgroup, \(G/K\) is contractible and \(BK\to BG\) is a homotopy equivalence in the usual classifying-space theory. This assertion is not a theorem for an arbitrary topological group merely possessing some compact subgroup.',r'\citet[Introduction]{gelfandfuchs1967topology} explicitly starts from this loss of information and motivates the new characteristic theory.',('gelfandfuchs1967topology',),reconstruction=r'The Lie-group and finite-component hypotheses are restored.')
item(132,'P000209','problem','A classifying theory retaining the noncompact group',r'Gelfand asks for the actual classifying space of a noncompact group, without identifying it with its maximal compact subgroup; bases should be Hausdorff, with a new local-triviality requirement agreeing with the usual one on completely regular bases.',r'For a closed linear Lie group \(G\), construct a category of principal \(G\)-bundles over Hausdorff spaces, together with sufficiently large universal objects, such that ordinary locally trivial bundles over completely regular bases are included and natural characteristic operations retain information about \(G\), not merely the homotopy type of \(BG\).',r'\citet[\S\S1--2 and 4]{gelfandfuchs1967topology} supplies the intended category, universal frame spaces, cohomological calculation, and classification of natural operations. The scope is a specified category and an arbitrarily large index set; it is not one ordinary CW space classifying all such bases.',('gelfandfuchs1967topology',),cls='A',problem='GP-1967-01',reconstruction=r'The informal request is made precise by the definitions and theorems in the three consecutive Fuchs talks.',status=r'As of November 2026, this precise linear-group programme is answered by the 1967 paper, with a more general elementary-object formulation in 1968. The broad phrase actual classifying space alone does not define an additional open problem.',speaker='I. M. Gelfand')
item(132,'P000210','method','The rejected cone test and Kazhdan\'s obstruction',r'For each \(x\), an equivariant map \(E\to CG\) is required to identify the fiber with the cone base. Kazhdan notes that cone height descends to a continuous real function on \(X\); the definition is rejected.',r'An equivariant map to \(CG\), nonzero on a selected fiber, yields a scalar height function on the base and a local equivariant chart on its nonzero set. Over a completely regular base a local chart can be multiplied by a continuous cutoff to produce such a map. Requiring this construction over arbitrary Hausdorff bases introduces scalar separation unavailable on the ray quotient considered next.',r'The successful frame-space replacement is given by \citet[\S1]{gelfandfuchs1967topology}; the exact cone objection is recorded in the seminar rather than promoted there to a separately numbered theorem.',('gelfandfuchs1967topology',),cls='A',match='partial',reconstruction=r'The obstruction explains why the criterion fails for the intended enlarged category. It does not assert that the cone criterion is logically inconsistent or fails for ordinary numerable bundles.',speaker='D. A. Kazhdan')
item(132,'P000210-P000211','definition','Global fiberwise linear charts over Hausdorff bases',r'For \(G\subset GL(n,\mathbb R)\), form \(E^\#=E\times_G\mathbb R^n\). For every prescribed base point there must be a continuous map \(E^\#\to\mathbb R^n\), linear on all fibers and invertible on the selected fiber.',r'Use the quotient topology on the associated vector bundle and require global continuous fiberwise linear maps that are isomorphisms on each individually chosen fiber. No support restriction is imposed. This condition implies the usual local trivialization around that fiber; it agrees with ordinary local triviality over completely regular bases. Over merely Hausdorff bases it is an additional specified condition, not a consequence of local triviality alone.',r'This is the principal-bundle category of \citet[\S1, definition preceding Proposition 1.1]{gelfandfuchs1967topology}. Its deliberate use of global linear maps replaces the unsuccessful scalar cutoff construction.',('gelfandfuchs1967topology',),cls='A',reconstruction=r'The quantifier for every chosen fiber and the distinction from arbitrary ordinary Hausdorff bundles are made explicit.')
item(132,'P000211','claim','Recovering the principal bundle requires its reduction',r'The first line says that \(E\) is recovered from \(E^\#\).',r'The full frame bundle of a rank-\(n\) vector bundle recovers a principal \(GL(n,\mathbb R)\)-bundle. For a proper closed subgroup \(G\), recovering the original principal \(G\)-bundle requires retaining its \(G\)-reduction inside that frame bundle. The underlying associated vector bundle alone generally forgets that reduction.',r'The frame construction in \citet[\S1]{gelfandfuchs1967topology} retains the group action. It does not justify an inverse from bare vector bundles for every subgroup \(G\).',('gelfandfuchs1967topology',),cls='E',literal='false as written',match='partial',reconstruction=r'The missing reduction is an elementary categorical correction, not a claim that the published construction fails.')
item(132,'P000211-P000212','construction','The Hausdorff ray quotient with no nonconstant scalar functions',r'For the additive group \(\mathbb R\) acting by positive homotheties, the total space is written \(\mathbb R^\infty\); the quotient \(S\) is Hausdorff but every continuous real function on it is constant. A cylinder-neighborhood argument is sketched.',r'Let \(E=\mathbb R^{\mathbb N}\setminus\{0\}\) have the product topology and let \(t\in\mathbb R\) act by \(x\mapsto e^t x\). The quotient of positive rays is Hausdorff and every continuous map \(S=E/\mathbb R\to\mathbb R\) is constant. The quotient bundle meets the specified global linear-chart condition. It has no continuous section: the coordinates of such a section would all be constant, making its image a single point.',r'The example and the cylinder proof occur in \citet[Introduction, pp.33--35 in the Russian original]{gelfandfuchs1967topology}. Deleting zero is indispensable to the free action and is explicit in the publication.',('gelfandfuchs1967topology',),cls='A',literal='correct with missing hypotheses',reconstruction=r'The zero vector is removed and the additive-to-multiplicative identification is specified.')
item(132,'P000211','claim','The proposed weighted cross-section is not a section of all rays',r'The notebook suggests examining the purported section \(\sum_{n\ge1}2^{-n}|x_n|/(1+|x_n|)=1/2\), to see that the resulting map is discontinuous.',r'This level set does not meet every nonzero positive ray. On a ray supported only at coordinate \(m\ge2\), the left side is always less than \(2^{-m}\le1/4\); for a ray supported only at coordinate 1 it tends to \(1/2\) but never reaches it. Consequently it cannot first define a global set-theoretic selector whose continuity is then tested.',r'The no-section theorem is independently proved in \citet[Introduction]{gelfandfuchs1967topology}; the specific displayed selector is not needed. The failure is an immediate calculation from the handwritten formula.',('gelfandfuchs1967topology',),cls='E',literal='false as written',match='none found',verification='indirect',reconstruction=r'The one-coordinate test is an editorial check. The literal denominator \(1+|x_n|\) and level \(1/2\) were checked against the scan.')
item(132,'P000212','theorem','Universal targets indexed by sufficiently large products',r'Every bundle maps to the ray-bundle model built from a product of copies of \(\mathbb R\) of sufficiently large cardinality; the map need not be unique.',r'In the specified category, collecting enough global fiberwise linear charts yields an equivariant map into a frame-space universal bundle indexed by a set \(I\) depending on the given bundle. In rank one this gives the positive-ray construction. Universality means existence of such a bundle morphism and pullback representation; it is not uniqueness of an actual map.',r'\citet[Proposition 1.1]{gelfandfuchs1967topology} proves the construction. The variable cardinality is a substantive part of the statement, developed explicitly at the next lecture.',('gelfandfuchs1967topology',),cls='A',problem='GP-1967-01',literal='correct')
correction('P000211','Ray-space total space',r'E=\mathbb R^\infty',r'E=\mathbb R^\infty\setminus\{0\}','The action is not free at zero; Gelfand--Fuchs1967 explicitly removes zero.')
correction('P000211','Recovery from associated vector bundle','E is recovered from E#','E is recovered from E# together with its G-reduction; for G=GL(n) the full frame bundle suffices','For a proper subgroup the associated vector bundle forgets the reduction; the unqualified handwritten sentence is too strong.')
correction('P000211','Weighted cross-section',r'\sum2^{-n}|x_n|/(1+|x_n|)=1/2 gives a selector',r'The displayed level does not meet all rays','A ray supported at coordinate m>=2 has supremum 2^{-m}<1/2. The formula is visible in the scan.')

talk(133,'1967-09-25','I. M. Gelfand','P000211-P000214','Feynman parameters and commuting interval maps',r'The date 25 September appears on P000212, after the first Fuchs lecture. Two Feynman-parameter identities are followed by news about commuting continuous interval maps and a differentiable periodic-point result. The three-denominator identity lacks a factorial; the interval remark refers to the counterexample work of Boyce and Huneke and to the earlier periodic-point theorem of Schwartz. Fuchs resumes under his own heading on P000213.')
item(133,'P000212','method','Two-denominator Feynman parametrization',r'\(1/(ab)=\int_0^1(at+b(1-t))^{-2}\,dt\), described as a good formula of Feynman and a partial-fraction decomposition.',r'For positive real \(a,b\), \[\frac1{ab}=\int_0^1\frac{dt}{(ta+(1-t)b)^2}.\] The same equality holds for nonzero complex \(a,b\) when the segment \(ta+(1-t)b\) avoids zero. At \(a=b\) the integrand is constant; otherwise integrate its elementary antiderivative.',r'This is the exponent-one instance of the beta-integral denominator identity; see \citet[\S5.12, Euler beta integral]{nist2026beta}. The seminar attribution names Feynman\'s useful parametrization, not a new result proved in 1967.',('nist2026beta',),reconstruction=r'The denominator-nonvanishing hypothesis and equal-parameter case are supplied.')
item(133,'P000212','claim','Three denominators and the missing factorial',r'\(1/(abc)=\int_\Delta(at_1+bt_2+ct_3)^{-3}\,dt_1dt_2\), where \(t_i\ge0\) and \(t_1+t_2+t_3=1\).',r'With ordinary coordinate measure \(dt_1dt_2\) on \(\Delta=\{t_1,t_2\ge0:t_1+t_2\le1\}\), and \(a,b,c>0\), the correct identity is \[\frac1{abc}=2\int_\Delta\frac{dt_1dt_2}{(at_1+bt_2+c(1-t_1-t_2))^3}.\] More generally the \(m\)-denominator numerator factor is \((m-1)!\) for unit powers.',r'The factor follows from the beta-integral normalization \citep[\S5.12]{nist2026beta}. Taking \(a=b=c=1\) already detects the error: the written right side equals the triangle\'s area \(1/2\).',('nist2026beta',),literal='false as written',reconstruction=r'The notebook explicitly uses \(dt_1dt_2\), so normalized probability measure on the simplex is not silently substituted.')
item(133,'P000212','theorem','Commuting continuous interval maps need not share a fixed point',r'The common-fixed-point hypothesis for two commuting continuous maps of an interval has a counterexample.',r'There exist continuous maps \(f,g:[0,1]\to[0,1]\) with \(f\circ g=g\circ f\) but \(\operatorname{Fix}(f)\cap\operatorname{Fix}(g)=\varnothing\). Thus the fixed-point property of an interval for individual maps does not extend to arbitrary commuting pairs.',r'\citet[main construction, pp.77--92]{boyce1969commuting} gives a counterexample. His paper was received 9 January 1967, revised 1 December 1967, and published in 1969; it cites Huneke\'s independent 1967 announcement. The notebook therefore records circulating results, not a problem still unresolved at the lecture.',('boyce1969commuting',),cls='E',literal='correct',problem='GP-1967-02',status=r'As of November 2026, the continuous common-fixed-point conjecture is false. The 1969 publication date must not conceal the 1967 circulation documented in the primary paper.')
item(133,'P000212','theorem','A fixed point of one map that is periodic for the other',r'If the commuting maps are differentiable, there is a point fixed for one and \ru{конечной кратности} for the other; the English translation says of finite multiplicity.',r'A precise established version is: if \(f:[0,1]\to[0,1]\) is continuously differentiable and \(g:[0,1]\to[0,1]\) is continuous with \(fg=gf\), then for some \(x\) and integer \(n\ge1\), \(f(x)=x\) and \(g^n(x)=x\). The Russian phrase here concerns finite period under iteration, not multiplicity of a zero.',r'The identifiable result is \citet[pp.353--355]{schwartz1965periodic}. The publisher metadata, the reference in \citet[references]{boyce1969commuting}, and the explicit statement in \citet[Introduction, pp.269--270]{alikhanikoopaei1998commuting} were checked; the Schwartz proof itself was not available in readable full text in this audit. Accordingly the exact weakening from \(C^1\) to merely differentiable maps is not asserted.',('schwartz1965periodic','boyce1969commuting','alikhanikoopaei1998commuting'),cls='E',match='partial',verification='indirect',reconstruction=r'The statement uses the verified \(C^1\) formulation and identifies finite multiplicity as finite period; it does not infer a common fixed point.',problem='GP-1967-02',confidence='medium')
correction('P000212','Three-denominator identity',r'1/(abc)=\int_\Delta(...)^{-3}dt_1dt_2',r'1/(abc)=2\int_\Delta(...)^{-3}dt_1dt_2','The missing 2! is in the scan. At a=b=c=1 the written integral is 1/2.')
correction('P000212','Commuting-map periodic-point remark','of finite multiplicity','of finite period','The context is iteration of commuting maps and Schwartz1965; multiplicity of a zero is not meant.','en','translation')
save()

talk(137,'1967-10-16','S. G. Krein','P000218-P000222','Interpolation, symmetric spaces, and Fourier coefficients',r'The Krein lecture begins on P000219 and ends in the middle of P000221 before the Sinai heading. It surveys classical interpolation, the Mityagin theorem, Lorentz refinements due to Dikarev and Matsaev, and Semenov\'s fundamental-function criteria and Fourier applications. The historical criteria are not all valid as stated: \citet[\S3]{sharpley1975interpolation} explicitly exhibits the defect in the Semenov theory. The corrected comparison uses Boyd dilation indices, not only values of the norm on characteristic functions.')
item(137,'P000219','definition','Interpolation pairs of compatible Banach couples',r'All four endpoint Banach spaces are embedded in a common topological linear space on each side; every endpoint-bounded linear operator must map the intermediate pair boundedly.',r'Let \((E_0,E_1)\) and \((F_0,F_1)\) be compatible Banach couples. Intermediate spaces satisfy \(E_0\cap E_1\hookrightarrow E\hookrightarrow E_0+E_1\) and similarly for \(F\). The pair \((E,F)\) is an interpolation pair if each linear \(A:E_0+E_1\to F_0+F_1\), bounded from \(E_i\) to \(F_i\) for \(i=0,1\), restricts boundedly from \(E\) to \(F\). Exactness is the stronger assertion that the intermediate operator norm is at most the maximum endpoint norm.',r'This is the standard operator-interpolation framework used by \citet[opening definitions]{mityagin1965interpolation} and \citet[\S2]{dikarevmatsaev1966exact}. The lecture later asks an exact-norm question, which must be distinguished from bounded interpolation.',('mityagin1965interpolation','dikarevmatsaev1966exact'),reconstruction=r'The common-domain sum space and the distinction between boundedness and exactness are supplied.')
item(137,'P000219','definition','Symmetric function spaces and basic inclusions',r'A Banach space of summable functions on \([0,1]\) is symmetric if it has the ideal property and its norm is invariant under measure-preserving transformations; then \(L_\infty\subset E\subset L_1\).',r'On the Lebesgue probability interval, a rearrangement-invariant Banach function space has the ideal property \(|f|\le|g|\Rightarrow\|f\|_E\le\|g\|_E\), and equimeasurable absolute values have equal norms. In the usual Banach-function-space setting, \(L^\infty\hookrightarrow E\hookrightarrow L^1\) continuously. A Fatou property, order continuity, or full symmetry is an additional property and must not be hidden inside the two displayed axioms.',r'The distinction matters in \citet[Theorems 1 and 3]{mityagin1965interpolation} and in \citet[\S1]{boyd1969indices}. It is precisely why the unqualified interpolation claims later in the notes require care.',('mityagin1965interpolation','boyd1969indices'),reconstruction=r'Equimeasurability and continuous inclusions are the modern formulation; the extra regularity assumptions are explicitly kept separate.')
item(137,'P000219','construction','Lorentz, associate Marcinkiewicz, and Orlicz examples',r'The examples are \(\int_0^1f^*\,d\psi\) for monotone \(\psi\), its dual norm \(\sup_e\int_e|f|/\psi(m(e))\), and Orlicz spaces including \(L^p\).',r'For an increasing concave function \(\psi\) with \(\psi(0)=0\) and \(\psi(t)>0\) for \(t>0\), the Lorentz norm is \(\|f\|_{\Lambda_\psi}=\int_0^1f^*(t)\,d\psi(t)\). Its associate norm is \(\sup_{0<t\le1}\psi(t)^{-1}\int_0^t f^*(s)\,ds\), equivalently the supremum over measurable sets of measure \(t\). For a Young function \(\Phi\), the Luxemburg Orlicz norm is \(\inf\{c>0:\int\Phi(|f|/c)\le1\}\); \(\Phi(u)=u^p\) gives \(L^p\).',r'Lorentz and associate spaces are used explicitly in \citet[\S1]{dikarevmatsaev1966exact} and \citet[\S1]{boyd1969indices}. Monotonicity alone is insufficient to guarantee that the displayed Lorentz functional is a Banach norm.',('dikarevmatsaev1966exact','boyd1969indices'),literal='correct with missing hypotheses',reconstruction=r'Concavity, positivity, the endpoint normalization, and the meaning of dual as associate norm are supplied.')
item(137,'P000219','theorem','Riesz--Thorin interpolation',r'The first step is named as the Riesz--Thorin theorem.',r'For a linear operator bounded \(L^{p_i}(\mu)\to L^{q_i}(\nu)\) with norms \(M_i\), \(1\le p_i,q_i\le\infty\), the standard complex interpolation theorem gives \(L^{p_\theta}\to L^{q_\theta}\) with norm at most \(M_0^{1-\theta}M_1^\theta\), where \(p_\theta^{-1}=(1-\theta)p_0^{-1}+\theta p_1^{-1}\) and similarly for \(q_\theta\). The operator must be consistently defined on the endpoint sum.',r'The theorem is background for the improvement discussed in \citet[Introduction]{dikarevmatsaev1966exact}. The notebook gives no separate proof or novelty claim.',('dikarevmatsaev1966exact',),match='partial',reconstruction=r'The full familiar statement fills in the named theorem; endpoint measurability conventions are the standard sigma-finite setting.')
item(137,'P000220','theorem','Weak endpoint bounds and Marcinkiewicz interpolation',r'The distribution-function bound is \(n_{Af}(\tau)^{1/q_i}\le C\|f\|_{p_i}/\tau\), described as weaker endpoint information.',r'This means \(\|Af\|_{L^{q_i,\infty}}\le C_i\|f\|_{L^{p_i}}\). For example, if \(1\le p_0<p_1<\infty\) and a sublinear operator has weak types \((p_0,p_0)\) and \((p_1,p_1)\), it is strongly bounded on \(L^p\) for \(p_0<p<p_1\). More general off-diagonal versions require their own exponent hypotheses; the two endpoint inequalities alone are not a statement about every possible intermediate exponent.',r'\citet[Introduction and \S2]{boyd1969indices} uses this precise weak-type framework, and \citet[Theorem 2]{dikarevmatsaev1966exact} gives the off-diagonal Lorentz version relevant here.',('boyd1969indices','dikarevmatsaev1966exact'),reconstruction=r'A safe diagonal theorem and the precise weak-space interpretation are separated from the later improving theorem.')
item(137,'P000220','theorem','The Dikarev--Matsaev Lorentz improvement and optimality',r'For improving operators \(q_i>p_i\), the intermediate image lies in a Lorentz space narrower than \(L^q\), and this image space is minimal for all operators with the endpoint bounds.',r'Take \(1<p_0<p_1<\infty\), distinct \(1<q_0,q_1<\infty\), and \(0<\theta<1\). Interpolation of weak endpoint maps gives \(L^{p,p}\to L^{q,p}\), where the reciprocal exponents are interpolated linearly. Since \(L^{p,p}=L^p\) and \(L^{q,p}\subset L^q\) when \(p<q\), this improves the target. The published sharpness theorem quantifies over all endpoint-admissible operators on nonatomic measure spaces, with an infinite source measure in its stated general form.',r'\citet[Theorems 2--3]{dikarevmatsaev1966exact}, received 25 September 1965 and published in 1966, gives both the target and the quantified optimality. This is earlier work being reported by Krein.',('dikarevmatsaev1966exact',),cls='E',match='partial',reconstruction=r'The Lorentz second index \(p\) and the measure-space restriction in the sharpness theorem are supplied; minimality is not asserted for every one fixed operator.')
item(137,'P000220','theorem','Mityagin exact interpolation and symmetric norms',r'Every contraction on \(L^1\) and \(L^\infty\) is a contraction on exactly the symmetric spaces; a two-dimensional square-and-diamond diagram motivates the statement.',r'In finite dimensions, operators contractive for both \(\ell^1\) and \(\ell^\infty\) contract every symmetric norm; signed coordinate permutations and their convex hull give the elementary model. In function spaces, Mityagin proves the corresponding exact interpolation theorem for minimal symmetric ideals, and separately for maximal ideals. A fully symmetric Banach function space is an exact interpolation space for \((L^1,L^\infty)\). The two symmetry axioms alone, without the relevant regularity or majorization property, must not be substituted for these hypotheses.',r'\citet[Theorems 1--3]{mityagin1965interpolation} is the exact named source, received 3 December 1963 and published in 1965. Its minimal/maximal qualifications are absent from the notebook.',('mityagin1965interpolation',),literal='correct with missing hypotheses',reconstruction=r'The finite-dimensional illustration and the infinite-dimensional theorem are distinguished. Full symmetry means monotonicity under Hardy--Littlewood submajorization.')
item(137,'P000220-P000221','definition','Fundamental function and dyadic ratios',r'\(\|\chi_e\|_E=\varphi(m(e))\); \(\ell_E=\liminf_{t\downarrow0}\varphi(2t)/\varphi(t)\), \(u_E=\limsup\), with \(1\le\ell_E\le u_E\le2\), and both equal \(2^{1/p}\) for \(L^p\).',r'For a rearrangement-invariant space on \([0,1]\), the fundamental function is \(\varphi_E(t)=\|\chi_{[0,t]}\|_E\). Monotonicity and the triangle inequality give \(1\le\varphi_E(2t)/\varphi_E(t)\le2\) when \(0<t\le1/2\). For \(L^p\), \(\varphi(t)=t^{1/p}\), with the standard interpretation for \(p=\infty\). These ratios measure only indicator functions, not the norm of the dilation operator on all of \(E\).',r'These are the invariants used in \citet[Theorem 1]{semenov1965interpolation}. Their distinction from dilation indices is made explicit in \citet[\S3]{sharpley1975interpolation}.',('semenov1965interpolation','sharpley1975interpolation'),literal='correct')
item(137,'P000221','claim','The fundamental-function criterion fails in full generality',r'Semenov\'s first theorem is recorded as: every operator bounded on all \(L^p\), \(1<p<\infty\), is bounded on \(E\) if and only if \(1<\ell_E\le u_E<2\).',r'The stated criterion is false for arbitrary symmetric spaces, even with separability added. The norm of every dilation, rather than only its values on indicators, controls the general interpolation property. For a rearrangement-invariant Banach function space with the Fatou property, writing the Boyd exponents in the convention \(0\le\beta_E\le\alpha_E\le1\), the correct nonendpoint condition is \(0<\beta_E\le\alpha_E<1\). More generally all weak-type \((p,p),(q,q)\) operators act on \(E\) exactly when \(1/q<\beta_E\le\alpha_E<1/p\).',r'The historical claim is \citet[Theorem 1]{semenov1965interpolation}; the later general argument appears in \citet{semenov1968interpolation}. \citet[\S3, pp.122--125]{sharpley1975interpolation} explicitly disproves the underlying theorem using a space with \(\varphi(t)=\sqrt t\) but an endpoint Boyd exponent. The replacement is \citet[Theorem 1]{boyd1969indices}.',('semenov1965interpolation','semenov1968interpolation','sharpley1975interpolation','boyd1969indices'),cls='E',literal='false as written',status=r'As of November 2026, the historical general criterion is refuted; its exact appearance in the literature is not evidence of correctness. Fundamental-function criteria remain valid in appropriately restricted classes where they control the dilation norms.',reconstruction=r'The modern Boyd-index theorem is a corrected replacement, not an assertion that Semenov used those indices. The all-\(L^p\) consequence follows by choosing finite endpoints around the Boyd exponents; the Hardy operators also show necessity.')
item(137,'P000221','claim','The improving symmetric-space criterion and its limitation',r'For operators \(L^{1/\alpha}\to L^{1/(\alpha-\Delta)}\), \(\alpha_0<\alpha<\alpha_1\), the notes assert \(E\to E_\Delta\) when \(2^{\alpha_0}<\ell_E\le u_E<2^{\alpha_1}\), with \(\|f\|_{E_\Delta}=\|t^{-\Delta}f^*(t)\|_E\).',r'The displayed target functional specializes, for \(E=L^p\) and \(0<\Delta<1/p\), to \(\bigl(\int_0^1[f^*(t)]^p t^{-p\Delta}dt\bigr)^{1/p}\), the Lorentz \(L^{q,p}\) functional with \(1/q=1/p-\Delta\). This correctly explains the classical improving case. The claimed extension to every symmetric \(E\), controlled only by its fundamental-function ratios, is not a valid general theorem; additional dilation or majorization hypotheses are needed.',r'\citet[Theorem 3]{semenov1967fourier} and \citet[Theorem 2]{semenov1968interpolation} are the exact historical continuation; the latter manuscript was received 7 June 1967. The inaccuracies and failed underlying representation theorem are documented in \citet[\S3]{sharpley1975interpolation}.',('semenov1967fourier','semenov1968interpolation','sharpley1975interpolation'),cls='B',literal='false as written',reconstruction=r'The exponent is read as \(1/(\alpha-\Delta)\), consistent with the target functional and improving-operator discussion. The general false claim is separated from its valid \(L^p\) specialization.',status=r'As of November 2026, the \(L^p\)-to-Lorentz specialization is established, while the unqualified fundamental-function extension is invalid. The printed 1968 theorem is a publication match, not a valid modern resolution.')
item(137,'P000221','theorem','Hausdorff--Young with the conjugate exponent',r'The written expression is \((|c_k|^p)^{1/p}\le\|f\|_{L^p}\), with no visible summation and with \(p\) on both sides.',r'On the probability circle, for \(1\le p\le2\) and \(p^{-1}+(p^{\prime})^{-1}=1\), the Fourier coefficients satisfy \(\|\widehat f\|_{\ell^{p^{\prime}}}\le\|f\|_{L^p}\). At \(p=1\) the target is \(\ell^\infty\). A bound on each individual coefficient is much weaker; an \(\ell^p\) bound for general \(p<2\) is not Hausdorff--Young.',r'This classical endpoint interpolation application is the baseline for \citet[Theorem 4]{dikarevmatsaev1966exact} and the Fourier estimates in \citet[\S2]{semenov1967fourier}.',('dikarevmatsaev1966exact','semenov1967fourier'),literal='false as written',match='partial',reconstruction=r'The conjugate exponent and summation or supremum are restored. The lack of a summation sign was confirmed in the scan.')
item(137,'P000221','theorem','Paley\'s rearranged-coefficient inequality',r'The heading is written \ru{Пойя}; the inequality is \((\sum_{k\ge1}k^{p-2}(c_k^*)^p)^{1/p}\le C\|f\|_p\).',r'For \(1<p\le2\), Fourier coefficients relative to a uniformly bounded orthonormal system satisfy \[\left(\sum_{k\ge1}k^{p-2}(c_k^*)^p\right)^{1/p}\le C_p\|f\|_{L^p},\] where \(c_k^*\) is the decreasing rearrangement of absolute coefficients. This is a Lorentz \(\ell^{p^{\prime},p}\) bound; for the trigonometric system the usual normalization only changes the constant.',r'\citet[Theorem 4]{dikarevmatsaev1966exact} gives the Lorentz estimate. \citet[Theorem 6 and the following paragraph]{semenov1967fourier} explicitly names the \(L^p\) specialization as Paley\'s theorem, supporting a mathematical-name emendation from the source\'s Poia/P\'olya heading.',('dikarevmatsaev1966exact','semenov1967fourier'),reconstruction=r'The exponent range, orthonormal-system hypotheses, and corrected attribution are supplied.')
item(137,'P000221','theorem','Hardy--Littlewood for monotone Fourier coefficients',r'Monotonically decreasing Fourier coefficients yield two-sided inequalities, attributed to Hardy and Littlewood.',r'For \(1<p<\infty\) and a nonnegative decreasing sequence \(a_n\to0\), the classical monotone sine-series theorem characterizes \(\sum_{n\ge1}a_n\sin nt\in L^p\) by \(\sum_{n\ge1}n^{p-2}a_n^p<\infty\), with equivalence of the corresponding norms. A parallel cosine-series formulation needs its constant coefficient included. Arbitrary rearrangements of coefficients do not give such a two-sided theorem.',r'\citet[Theorem 7 and its specialization paragraph]{semenov1967fourier} explicitly identifies the Hardy--Littlewood result. Its broader symmetric-space extension shares the fundamental-function difficulties discussed above; the classical \(L^p\) assertion is retained separately.',('semenov1967fourier',),match='partial',reconstruction=r'A definite monotone nonnegative sine-series version replaces the unspecified phrase Fourier coefficients.')
item(137,'P000221','claim','No Hilbert interpolation space between L1 and L3/2',r'The notes attribute to Semenov the absence of a Hilbert interpolation space between \(L_1\) and \(L_{1.5}\).',r'In the nonatomic function-space setting there is no rearrangement-invariant space isomorphic to a Hilbert space with continuous inclusions \(L^{3/2}\hookrightarrow E\hookrightarrow L^1\). Indeed Hilbert type and cotype, applied to disjoint equimeasurable indicators, force \(\varphi_E(1/n)\asymp n^{-1/2}\), while \(L^{3/2}\hookrightarrow E\) forces \(\varphi_E(1/n)\le Cn^{-2/3}\), a contradiction. Consequently no Hilbert interpolation space in this symmetric category exists.',r'The symmetry framework is that of \citet{mityagin1965interpolation}. No exact early Semenov publication for this isolated assertion was identified in the 1965, 1967, and 1968 papers inspected. The elementary argument establishes the qualified claim without assigning it to an unrelated theorem.',('mityagin1965interpolation',),cls='E',match='none found',verification='indirect',reconstruction=r'The disjoint-indicator argument is editorial. It uses nonatomicity and Banach-space isomorphism to Hilbert space, not merely equality of norms. The broader abstract-category formulation is not inferred.',confidence='medium')
item(137,'P000221','question','Gelfand\'s request for an abstract description',r'Gelfand asks for an abstract description of interpolation spaces; the parenthesis says it is unknown whether they are function spaces.',r'The notes do not specify a Banach couple, the operator category, an isometric versus isomorphic representation, or a required lattice structure. Thus several inequivalent representation and classification questions fit the wording, and no unique quantified conjecture can be extracted.',r'The inspected Mityagin, Semenov, Boyd, and Sharpley papers address specified function-space interpolation problems. They do not provide an exact match to this unrestricted question. It is retained as an identifiable programme remark, without an invented open-problem identifier.',('mityagin1965interpolation','boyd1969indices'),cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',status=r'As of November 2026, the historical question remains underdetermined by this record. It should not be reported as a single still-open theorem problem.',speaker='I. M. Gelfand',confidence='high')
correction('P000219','Lorentz functional','psi monotone','psi increasing and concave, psi(0)=0, psi(t)>0 for t>0','Monotonicity alone does not ensure a Banach Lorentz norm; the standard hypotheses appear in Semenov1967.')
correction('P000220','Mityagin theorem','symmetric is necessary and sufficient without qualification','Retain the minimal/maximal, order-continuity, Fatou, or full-symmetry hypotheses of the chosen theorem','Mityagin1965 Theorems1 and3 distinguish the required function-space categories.')
correction('P000221','Semenov fundamental-function criterion',r'1<ell_E<=u_E<2 is sufficient for arbitrary symmetric E','The unrestricted theorem is false; use dilation indices or additional structural hypotheses','Sharpley1975 pp122-125 explicitly refutes the underlying Semenov1968 representation theorem and records its consequences.')
correction('P000221','Improving target exponent',r'L_{1/alpha-Delta}',r'L_{1/(alpha-Delta)} is the coherent intended reading','The scan does not group the diagonal fraction unambiguously; the E_Delta formula gives reciprocal exponent alpha-Delta.','both','ambiguity')
correction('P000221','Hausdorff--Young',r'(|c_k|^p)^{1/p}<=||f||_p',r'||c||_{ell^{p prime}}<=||f||_p, 1<=p<=2','The scan contains no sum and uses p rather than its conjugate; these are mathematical emendations, not claimed OCR mistakes.')
correction('P000221','Weighted coefficient inequality name','Poia / Пойя','Paley / Пале','Semenov1967 explicitly identifies this exact Lp weighted rearranged-coefficient specialization as Paley; the scan itself reads Пойя.')
